53	/** Owns trigger-specific schedule form state at schedule-section boundary. */
54	export class ActionScheduleStore extends EventTarget {
55	    private readonly accountResetDraft: AccountResetDraft = { agent: '', limitId: '', windowId: '' }
56	    private readonly cardStateDraft: CardStateDraft = { cardInternalId: '', targetState: '' }
57	    private snapshot: ActionScheduleStoreSnapshot = INITIAL_SNAPSHOT
58	    private timestamp = ''
59	
60	    readonly getSnapshot = () => this.snapshot
61	    readonly getOpenSnapshot = () => this.snapshot.open
62	
63	    readonly subscribe = (listener: () => void) => {
64	        this.addEventListener('changed', listener)
65	
66	        return () => this.removeEventListener('changed', listener)
67	    }
68	
69	    toggle(anchorElement: HTMLElement) {
70	        if (this.snapshot.open) {
71	            this.close()
72	            return
73	        }
74	
75	        this.publish({ ...this.snapshot, anchorElement, message: null, open: true })
76	    }
77	
78	    close() {
79	        const { anchorElement, message, open } = this.snapshot
80	        if (!open && anchorElement === null && message === null) return
81	
82	        this.publish({ ...this.snapshot, anchorElement: null, message: null, open: false })
83	    }
84	
85	    setTriggerType(triggerType: ActionScheduleTriggerType) {
86	        if (triggerType === this.snapshot.triggerType) return
87	
88	        const common = { anchorElement: this.snapshot.anchorElement, message: null, open: this.snapshot.open }
89	        if (triggerType === 'at') {
90	            this.publish({ ...common, timestamp: this.timestamp, triggerType })
91	            return
92	        }
93	        if (triggerType === 'account-reset') {
94	            this.publish({ ...common, ...this.accountResetDraft, triggerType })
95	            return
96	        }
97	
98	        this.publish({ ...common, ...this.cardStateDraft, triggerType })
99	    }
100	
101	    setTimestamp(timestamp: string) {
102	        this.timestamp = timestamp
103	        if (this.snapshot.triggerType === 'at') this.publish({ ...this.snapshot, message: null, timestamp })
104	    }
105	
106	    setAgent(agent: string) {
107	        this.accountResetDraft.agent = agent
108	        this.accountResetDraft.limitId = ''
109	        this.accountResetDraft.windowId = ''
110	        if (this.snapshot.triggerType === 'account-reset') {
111	            this.publish({ ...this.snapshot, ...this.accountResetDraft, message: null })
112	        }
113	    }
114	
115	    setAccountTracker(limitId: string, windowId: string) {
116	        this.accountResetDraft.limitId = limitId
117	        this.accountResetDraft.windowId = windowId
118	        if (this.snapshot.triggerType === 'account-reset') {
119	            this.publish({ ...this.snapshot, ...this.accountResetDraft, message: null })
120	        }
121	    }
122	
123	    setCardInternalId(cardInternalId: string) {
124	        this.cardStateDraft.cardInternalId = cardInternalId
125	        if (this.snapshot.triggerType === 'card-state') {
126	            this.publish({ ...this.snapshot, cardInternalId, message: null })
127	        }
128	    }
129	
130	    setTargetState(targetState: string) {
131	        this.cardStateDraft.targetState = targetState
132	        if (this.snapshot.triggerType === 'card-state') {
133	            this.publish({ ...this.snapshot, message: null, targetState })
134	        }
135	    }
136	
137	    setMessage(message: string | null) {
138	        this.publish({ ...this.snapshot, message })
139	    }
140	
141	    private publish(snapshot: ActionScheduleStoreSnapshot) {
142	        this.snapshot = snapshot
143	        this.dispatchEvent(new Event('changed'))
144	    }
145	}
