43	/** Open schedule popover; subscribes to card, rate-limit, and config sources only while mounted. */
44	export function ActionSchedulePopover(
45	    { accountId, action, context, conversationId, promptDraft, selectionValidationError, store }: ActionSchedulePopoverProps,
46	) {
47	    const snapshot = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot)
48	    const activeCards = useSyncExternalStore(subscribeActiveCards, getActiveCards, getActiveCards)
49	    // Account-reset trackers name no account yet, so they follow the selected default account of each agent.
50	    const claudeState = useClaudeRateLimits(useSelectedAgentAccountId('claude'))
51	    const codexState = useCodexRateLimits(useSelectedAgentAccountId('codex'))
52	    const projectConfig = useProjectConfig()
53	    const sources: ActionScheduleTriggerSources = {
54	        accountTrackers: accountTrackerOptions(claudeState, codexState),
55	        cards: cardScheduleOptions(activeCards, context.cardInternalId),
56	        targetStates: scheduleTargetStates(projectConfig?.states),
57	    }
58	    const handleChange = (change: ActionScheduleFormChange) => {
59	        if (change.type === 'trigger-type') store.setTriggerType(change.triggerType)
60	        else if (change.type === 'timestamp') store.setTimestamp(change.timestamp)
61	        else if (change.type === 'agent') store.setAgent(change.agent)
62	        else if (change.type === 'tracker') store.setAccountTracker(change.limitId, change.windowId)
63	        else if (change.type === 'card') store.setCardInternalId(change.cardInternalId)
64	        else store.setTargetState(change.targetState)
65	    }
66	    const handleRegister = async () => {
67	        store.setMessage(null)
68	        try {
69	            if (selectionValidationError) throw new Error(selectionValidationError)
70	            promptDraft.requestFlush()
71	            const prompt = promptDraft.getSnapshot()
72	            const trigger = createScheduleTrigger(store.getSnapshot(), sources)
73	            await defaultScheduleAction(action, context, trigger, prompt, conversationId ?? undefined, accountId)
74	            store.close()
75	        } catch (error) {
76	            dialogService.error(error, { fallbackMessage: 'Could not register schedule' })
77	        }
78	    }
79	    const handleClose = () => store.close()
80	
81	    return (
82	        <Popover
83	            anchorEl={snapshot.anchorElement}
84	            anchorOrigin={{ horizontal: 'right', vertical: 'top' }}
85	            onClose={handleClose}
86	            open={snapshot.open}
87	            slotProps={{
88	                paper: {
89	                    'aria-label': 'Schedule action',
90	                    elevation: SCHEDULE_POPOVER_ELEVATION,
91	                    role: 'dialog',
92	                    sx: {
93	                        bgcolor: 'background.paper', border: '1px solid', borderColor: 'divider',
94	                        maxWidth: (theme) => `calc(100vw - ${theme.spacing(4)})`, p: 2, width: SCHEDULE_POPOVER_WIDTH,
95	                    },
96	                },
97	            }}
98	            transformOrigin={{ horizontal: 'right', vertical: 'bottom' }}
99	        >
100	            <ActionScheduleForm
101	                accountTrackers={sources.accountTrackers}
102	                canRegister={canRegisterSchedule(snapshot, sources)}
103	                cards={sources.cards}
104	                message={snapshot.message}
105	                onChange={handleChange}
106	                onRegister={handleRegister}
107	                snapshot={snapshot}
108	                targetStates={sources.targetStates}
109	            />
110	        </Popover>
111	    )
112	}
