18	/** Finds the running schedule whose current step belongs to the given agent conversation. */
19	function findRunningScheduleForConversation(schedules, conversationId) {
20	    return schedules.find((schedule) => schedule.status === 'running' && schedule.conversationId === conversationId) ?? null;
21	}
22	
23	function pendingTimedScheduleIds(schedules) {
24	    return new Set(schedules
25	        .filter((schedule) => schedule.status === 'pending'
26	            && (schedule.trigger.type === 'at' || schedule.trigger.type === 'account-reset'))
27	        .map((schedule) => schedule.id));
28	}
29	
30	function pendingScheduleIds(schedules) {
31	    return new Set(schedules.filter(({ status }) => status === 'pending').map(({ id }) => id));
32	}
33	
34	function activeSchedules(schedules) {
35	    return schedules.filter(({ status }) => status === 'failed' || status === 'pending' || status === 'running');
36	}
