38	function deleteScheduleRecord(schedules, scheduleId) {
39	    const schedule = schedules.find(({ id }) => id === scheduleId);
40	    if (!schedule) throw new Error(`Schedule not found: ${scheduleId}`);
41	
42	    return createActionScheduleFile(schedules.filter(({ id }) => id !== scheduleId)).schedules;
43	}
